using System.Collections;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HealbotEffect", menuName = "Data/Battle/Effects/Hevelius/Healbot Effect")]
public class HealbotEffect : Effect
{
	[Header("Description")]
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private BattleActionToRandomEnemyOmenLogic battleActionToRandomEnemyOmenLogic;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedAtTheEndOfYourTurn = base.localizationManager.GetLocalizedAtTheEndOfYourTurn(withSpace: true);
		string actionDescription = battleAction.GetActionDescription(amount);
		return string.Concat(localizedAtTheEndOfYourTurn + actionDescription, "\n", GetLocalizedDescription(), AppendedDescription());
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfflictionReliefHealbotForcefulStreamAction(HealbotCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator HealbotCoroutine(int effectAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.3f);
		PlayEffectActivationSFX();
		SpawnVFX(GetVFXOwnerPosition(effectOwner));
		if (IsVFXEnabled())
		{
			GameObject thirdVFX = GetThirdVFX(GetVFXOwnerPosition(effectOwner));
			TransformExtensions.SetLocalEulerAnglesZ(value: (effectOwner.GetComponent<CompanionInitializer>().PositioningIndex == 0) ? (-170) : 10, t: thirdVFX.transform.GetFirstChild());
		}
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		GameObject playerGameObject = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject;
		playerGameObject.GetComponent<CorruptionStats>().Purify(effectAmount, null, CorruptionPurifyModifierEnum.HEALBOT);
		SpawnSecondVFX(GetVFXOwnerPosition(playerGameObject));
		yield return new WaitForSeconds(0.5f);
	}

	public void PurificationExceedDealRandomEnemyPurification(int purificationAmount)
	{
		battleActionToRandomEnemyOmenLogic.ActivateOmen(null, purificationAmount, null, null);
	}
}
